import{_ as o,o as t,c as e,a5 as c}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"2.8로 업그레이드","description":"","frontmatter":{"title":"2.8로 업그레이드","order":2},"headers":[],"relativePath":"ko/latest/tutorial/upgrade-2.8.md","filePath":"ko/latest/tutorial/upgrade-2.8.md","lastUpdated":1788455378000}'),a={name:"ko/latest/tutorial/upgrade-2.8.md"};function r(n,d,i,K,_,s){return t(),e("div",null,[...d[0]||(d[0]=[c('<h1 id="_2-8로-업그레이드" tabindex="-1">2.8로 업그레이드 <a class="header-anchor" href="#_2-8로-업그레이드" aria-label="Permalink to &quot;2.8로 업그레이드&quot;">​</a></h1><p>2.8은 런타임, 컴파일러, 플러그인 구조를 다시 설계하고 공개 API 이름을 통일했습니다. 먼저 프로젝트를 백업한 다음 기존 플러그인 디렉터리 전체를 2.8로 교체하고 Godot을 다시 여세요.</p><p>알려진 플러그인 경로와 Autoload 이름은 자동으로 이전됩니다. UID가 있는 장면과 리소스 참조는 보통 새 위치로 자동 해석됩니다. 사용자 GDScript는 수정하지 않으므로 이전 타입 이름은 직접 변경해야 합니다.</p><table tabindex="0"><thead><tr><th>2.7.4</th><th>2.8</th></tr></thead><tbody><tr><td><code>KND_DialogueManager</code></td><td><code>KonadoDialogueManager</code></td></tr><tr><td><code>KND_Shot</code></td><td><code>KonadoShot</code></td></tr><tr><td><code>KND_SaveSystem</code></td><td><code>KonadoSaveSystem</code></td></tr><tr><td><code>KND_SaveData</code></td><td><code>KonadoSaveData</code></td></tr><tr><td><code>KND_Settings</code></td><td><code>KonadoSettings</code></td></tr><tr><td><code>KND_SettingCategory</code></td><td><code>KonadoSettingCategory</code></td></tr><tr><td><code>KND_SettingItem</code></td><td><code>KonadoSettingItem</code></td></tr><tr><td><code>KND_SettingsUIFactory</code></td><td><code>KonadoSettingsUIFactory</code></td></tr><tr><td><code>KND_AchievementManager</code></td><td><code>KonadoAchievements</code></td></tr><tr><td><code>KND_I18n</code></td><td><code>KonadoStoryLocalization</code></td></tr><tr><td><code>KND_Background</code> / <code>KND_BackgroundList</code></td><td><code>KonadoBackground</code> / <code>KonadoBackgroundList</code></td></tr><tr><td><code>KND_Character</code> / <code>KND_CharacterList</code></td><td><code>KonadoCharacter</code> / <code>KonadoCharacterList</code></td></tr><tr><td><code>KND_CharacterSceneBase</code></td><td><code>KonadoCharacterSceneBase</code></td></tr><tr><td><code>KND_CharacterTransitionFrame</code></td><td><code>KonadoCharacterTransitionFrame</code></td></tr><tr><td><code>KND_Actor</code></td><td><code>KonadoActor</code></td></tr><tr><td><code>KND_ActingInterface</code></td><td><code>KonadoStageController</code></td></tr><tr><td><code>KND_Bgm</code> / <code>KND_BgmList</code></td><td><code>KonadoBackgroundMusic</code> / <code>KonadoBackgroundMusicList</code></td></tr><tr><td><code>DialogVoice</code> / <code>DialogVoiceList</code></td><td><code>KonadoVoice</code> / <code>KonadoVoiceList</code></td></tr><tr><td><code>KND_SoundEffect</code> / <code>KND_SoundEffectList</code></td><td><code>KonadoSoundEffect</code> / <code>KonadoSoundEffectList</code></td></tr><tr><td><code>KND_AudioInterface</code></td><td><code>KonadoAudioController</code></td></tr><tr><td><code>KND_DialogueBox</code></td><td><code>KonadoDialogueBox</code></td></tr><tr><td><code>KND_Dialogue</code> / <code>KND_DialogueChoice</code></td><td>읽기 전용 <code>KonadoInstruction</code></td></tr><tr><td><code>KND_ScreenText</code></td><td><code>KonadoScreenText</code></td></tr><tr><td><code>KND_TypewriterText</code></td><td><code>KonadoTypewriterText</code></td></tr><tr><td><code>KND_Data</code></td><td><code>KonadoData</code></td></tr><tr><td><code>KND_VariableStore</code></td><td><code>KonadoVariableStore</code></td></tr><tr><td><code>KND_BackgroundSceneBase</code></td><td><code>KonadoBackgroundSceneBase</code></td></tr><tr><td><code>KND_ActorMotionLayer</code></td><td><code>KonadoActorMotionLayer</code></td></tr><tr><td><code>KonadoCamera2D</code></td><td><code>KonadoCameraMarker</code></td></tr><tr><td><code>KND_Logger</code></td><td><code>KonadoLogger</code></td></tr></tbody></table><p>문자열로 저장한 이전 플러그인 경로도 갱신하세요. UID로 정상 해석되는 일반 장면 참조는 직접 바꿀 필요가 없습니다.</p><p>이전 <code>KND_CharacterStatus</code> 리소스는 캐릭터 장면 상태 프로토콜과 <code>status_aliases</code>로 대체되었습니다. <code>KND_BackgroundTransitionLayer</code>를 직접 생성하지 말고 배경 전환은 <code>KonadoStageController</code>에 맡기세요. <code>KonadoScriptsInterpreter</code>를 직접 사용하던 도구는 <code>KonadoScriptCompiler</code>로 <code>KonadoProgram</code>을 만들고 <code>KonadoDialogueManager</code>에서 재생하도록 이전해야 합니다.</p><p><code>.ks</code> 소스는 2.8 컴파일러로 다시 임포트됩니다. 2.7에서 생성된 컴파일 캐시는 복사하지 마세요. 2.7 저장 데이터는 2.8에서 복원할 수 없으며 명확하게 거부됩니다. 2.8에서 따옴표가 없는 대화 화자는 배우 ID입니다. 텍스트 레이블로 사용할 때는 따옴표로 감싸세요.</p><p>업그레이드 후 GDScript 구문 분석 오류가 없는지 확인하고 모든 <code>.ks</code>를 다시 임포트한 뒤 시작, 스크립트 간 점프, 저장/불러오기, 언어 전환을 실제로 테스트하세요.</p>',8)])])}const l=o(a,[["render",r]]);export{g as __pageData,l as default};
